"""Independent host checks of actual UC1/C3 board-generated bytes and IQ."""
import binascii
import ctypes as C
import unittest
import numpy as np
from scipy.signal import resample_poly
from python.perf_test.tests.test_b2z_control_generator import ControlGeneratorTests, Packet, read_bytes
from python.perf_test.tests.test_compact_generator import CompactMeta
from python.perf_test.tests.test_bluebee_gen_waveform import iq_complex, demodulate_center_bits
from python.zigbee_rx.tests.test_zigbee_receiver import decode
from python.exadv_rx.protocol import whiten, crc24


class UC1Tests(unittest.TestCase):
    setUpClass = classmethod(ControlGeneratorTests.setUpClass.__func__)
    tearDownClass = classmethod(ControlGeneratorTests.tearDownClass.__func__)

    def setUp(self):
        self.build = self.lib.b2z_uc1_build
        self.build.argtypes = [C.POINTER(Packet), C.c_uint32, C.c_uint32, C.c_uint8]
        self.lib.b2z_compact_get_meta.restype = C.POINTER(CompactMeta)
        self.lib.b2z_uc1_cost.argtypes = [C.c_uint32, C.c_uint32, C.c_uint8]

    def check_record(self, data, p, n, side):
        self.assertEqual(len(data), 26+n)
        self.assertEqual(data[:2], bytes([0xc1, 0x11 if p.command_id else 0x10]))
        self.assertEqual(int.from_bytes(data[-2:], 'little'), binascii.crc_hqx(data[:-2], 0xffff))
        self.assertEqual(int.from_bytes(data[2:4], 'little'), p.run_id)
        self.assertEqual(int.from_bytes(data[4:8], 'little'), p.slot_index)
        self.assertEqual(int.from_bytes(data[8:10], 'little'), p.period_ms)
        self.assertEqual(int.from_bytes(data[10:14], 'little'), p.command_id)
        self.assertEqual(data[23], n)
        if p.command_id:
            self.assertEqual(p.ref_tick_ms + int.from_bytes(data[19:21], 'little'), p.valid_until_ms)
            self.assertEqual(p.ref_tick_ms + int.from_bytes(data[21:23], 'little'), p.execute_at_ms)
            state = 0xB2430100 ^ (p.run_id << 16) ^ p.command_id ^ (side*0x9e3779b9)
            expected = []
            for _ in range(n):
                state = (state*1664525 + 1013904223) & 0xffffffff
                expected.append(state >> 24)
            self.assertEqual(data[24:-2], bytes(expected))
        else:
            self.assertEqual(data[10:23], bytes(13))
            self.assertEqual(data[24:-2], bytes(n))

    def test_modes_costs_and_independent_iq(self):
        p = Packet(2701, 10, 5000, 500, 1, 8000, 7500, 1, 1, 7, 2, 1, 8)
        for b,z,cost,lc_cost in [(0,0,1648,1456),(1,0,1656,1464),(26,0,1856,2904),(2,6,1856,2344)]:
            for mode in (1,2,3):
                self.assertEqual(self.build(C.byref(p),b,z,mode),0)
                m=self.lib.ble_exadv_secondary_gen_get_last_meta().contents
                ble=read_bytes(m.ble_control_record,26+b)
                ieee=read_bytes(m.zigbee_payload,26+z)
                self.check_record(ble,p,b,1); self.check_record(ieee,p,z,2)
                self.assertEqual(self.lib.b2z_uc1_cost(b,z,mode), lc_cost if mode==3 else cost)
                if mode != 3:
                    self.assertEqual(m.pdu_len-2,179+b+4*z if mode==1 else 43+b)
                    self.assertEqual(m.primary_air_us+m.air_us+m.ieee_air_us,cost)
                    ll=read_bytes(m.ll_payload,m.ll_payload_len)
                    raw=whiten(ll[5:],3)
                    self.assertEqual(raw[-3:],crc24(raw[:-3]))
                    self.assertEqual(raw[:-3],read_bytes(m.pdu,m.pdu_len))
                else:
                    lc=self.lib.b2z_compact_get_meta().contents
                    expected_count=1 if b<=1 else (26+b+11)//12
                    self.assertEqual(lc.ble_count,expected_count)
                    self.assertEqual(sum(lc.air_us[:lc.ble_count])+m.ieee_air_us,lc_cost)
                    chunks=[]
                    for k in range(lc.ble_count):
                        iq=iq_complex(np.ctypeslib.as_array(lc.iq[k],shape=(lc.iq_bytes[k]//4,))[::2])
                        bits=demodulate_center_bits(iq,lc.air_us[k])
                        ll=np.packbits(bits,bitorder='little').tobytes()
                        raw=whiten(ll[5:],39)
                        self.assertEqual(raw[-3:],crc24(raw[:-3]))
                        data=raw[12:-3]
                        if expected_count==1: chunks.append(data)
                        else:
                            self.assertEqual(data[:2],b'\xc3\x01')
                            self.assertEqual(int.from_bytes(data[2:4],'little'),p.run_id)
                            self.assertEqual(int.from_bytes(data[4:8],'little'),p.slot_index)
                            self.assertEqual(int.from_bytes(data[8:12],'little'),p.command_id)
                            self.assertEqual(data[12:15],bytes([k,expected_count,26+b]))
                            self.assertEqual(len(data[15:]),min(12,26+b-12*k))
                            chunks.append(data[15:])
                    self.assertEqual(b''.join(chunks),ble)
                # Decode the actual joint or standalone waveform with IEEE receiver.
                ptr=m.iq_words if mode==1 else m.ieee_iq_words
                size=m.iq_byte_count if mode==1 else m.ieee_iq_byte_count
                iq=iq_complex(np.ctypeslib.as_array(ptr,shape=(size//4,))[::2])
                iq4=resample_poly(iq,25,192).astype(np.complex64)
                _,records=decode(np.concatenate((np.zeros(400,np.complex64),iq4,np.zeros(1200,np.complex64))),sample_rate=4000000)
                valid=[r for r in records if r['fcs_ok']]
                self.assertEqual([bytes.fromhex(r['payload_hex']) for r in valid],[ieee])

    def test_retries_sync_padding_and_validation(self):
        p=Packet(2702,10,5000,500,9,8000,7500,1,1,7,2,1,8)
        original=None
        for slot in (10,11,12,13):
            p.slot_index=slot;p.ref_tick_ms=slot*500
            self.assertEqual(self.build(C.byref(p),2,6,1),0)
            m=self.lib.ble_exadv_secondary_gen_get_last_meta().contents
            data=read_bytes(m.zigbee_payload,32)
            self.check_record(data,p,6,2)
            if original is None: original=data[24:-2]
            self.assertEqual(data[24:-2],original)
        p.slot_index=16;p.ref_tick_ms=8000
        self.assertEqual(self.build(C.byref(p),0,0,1),-1)
        p=Packet(2702,7,3500,500,0,0,0,0,0,0,0,0,0)
        self.assertEqual(self.build(C.byref(p),26,0,3),0)
        m=self.lib.ble_exadv_secondary_gen_get_last_meta().contents
        self.check_record(read_bytes(m.ble_control_record,52),p,26,1)
        self.assertEqual(self.lib.b2z_compact_get_meta().contents.ble_count,5)
        for b,z,mode in [(27,0,1),(3,6,1),(0,7,1),(0,0,0),(0,0,4)]:
            self.assertEqual(self.build(C.byref(p),b,z,mode),-1)
        p.ble_arg=1
        self.assertEqual(self.build(C.byref(p),0,0,1),-1)
        p.ble_arg=0;p.ref_tick_ms=3499
        self.assertEqual(self.build(C.byref(p),0,0,1),-1)
        p=Packet(2702,0,0,500,1,65536,2000,1,1,1,2,1,2)
        self.assertEqual(self.build(C.byref(p),0,0,1),-1)
        p.execute_at_ms=65535
        self.assertEqual(self.build(C.byref(p),0,0,1),0)
        p.ble_opcode=0
        self.assertEqual(self.build(C.byref(p),0,0,1),-1)

if __name__=='__main__': unittest.main()
